const BARITONE_SETTINGS = [{"name":"allowBreak","type":"Boolean","defaultValue":"true","category":"Передвижение","description":"Allow Baritone to break blocks","descriptionRu":"Разрешает или запрещает использование разрушения."},{"name":"allowBreakAnyway","type":"List<Block>","defaultValue":"","category":"Передвижение","description":"Blocks that baritone will be allowed to break even with allowBreak set to false","descriptionRu":"Разрешает или запрещает использование разрушения «anyway»."},{"name":"allowSprint","type":"Boolean","defaultValue":"true","category":"Передвижение","description":"Allow Baritone to sprint","descriptionRu":"Разрешает или запрещает использование бега."},{"name":"allowPlace","type":"Boolean","defaultValue":"true","category":"Передвижение","description":"Allow Baritone to place blocks","descriptionRu":"Разрешает или запрещает использование установки блоков."},{"name":"allowPlaceInFluidsSource","type":"Boolean","defaultValue":"true","category":"Передвижение","description":"Allow Baritone to place blocks in fluid source blocks","descriptionRu":"Разрешает или запрещает использование установки блоков «in» «fluids» «source»."},{"name":"allowPlaceInFluidsFlow","type":"Boolean","defaultValue":"true","category":"Передвижение","description":"Allow Baritone to place blocks in flowing fluid","descriptionRu":"Разрешает или запрещает использование установки блоков «in» «fluids» «flow»."},{"name":"allowInventory","type":"Boolean","defaultValue":"false","category":"Инвентарь","description":"Allow Baritone to move items in your inventory to your hotbar","descriptionRu":"Разрешает или запрещает использование инвентаря."},{"name":"ticksBetweenInventoryMoves","type":"Integer","defaultValue":"1","category":"Инвентарь","description":"Wait this many ticks between InventoryBehavior moving inventory items","descriptionRu":"Настраивает параметр: тиков «between» инвентаря «moves». Раздел: Инвентарь."},{"name":"inventoryMoveOnlyIfStationary","type":"Boolean","defaultValue":"false","category":"Инвентарь","description":"Come to a halt before doing any inventory moves. Intended for anticheat such as 2b2t","descriptionRu":"Включает или отключает функцию: инвентаря «move» «only» «if» «stationary»."},{"name":"assumeExternalAutoTool","type":"Boolean","defaultValue":"false","category":"Инвентарь","description":"Disable baritone's auto-tool at runtime, but still assume that another mod will provide auto tool functionality Specifically, path calculation will still assume that an auto tool will run at execution time, even though Baritone itself will not do that.","descriptionRu":"Учитывает «external» автоматического режима инструмента при расчёте маршрута."},{"name":"autoTool","type":"Boolean","defaultValue":"true","category":"Инвентарь","description":"Automatically select the best available tool","descriptionRu":"Включает или отключает функцию: автоматического режима инструмента."},{"name":"blockPlacementPenalty","type":"Double","defaultValue":"20","category":"Поиск пути","description":"It doesn't actually take twenty ticks to place a block, this cost is so high because we want to generally conserve blocks which might be limited. Decrease to make Baritone more often consider paths that would require placing blocks","descriptionRu":"Настраивает стоимость или приоритет: блока установки блоков штрафа."},{"name":"blockBreakAdditionalPenalty","type":"Double","defaultValue":"2","category":"Поиск пути","description":"This is just a tiebreaker to make it less likely to break blocks if it can avoid it. For example, fire has a break cost of 0, this makes it nonzero, so all else being equal it will take an otherwise equivalent route that doesn't require it to put out fire.","descriptionRu":"Настраивает стоимость или приоритет: блока разрушения «additional» штрафа."},{"name":"jumpPenalty","type":"Double","defaultValue":"2","category":"Поиск пути","description":"Additional penalty for hitting the space bar (ascend, pillar, or parkour) because it uses hunger","descriptionRu":"Настраивает стоимость или приоритет: прыжка штрафа."},{"name":"walkOnWaterOnePenalty","type":"Double","defaultValue":"3","category":"Безопасность","description":"Walking on water uses up hunger really quick, so penalize it","descriptionRu":"Настраивает стоимость или приоритет: ходьбы «on» воды «one» штрафа."},{"name":"strictLiquidCheck","type":"Boolean","defaultValue":"false","category":"Прочее","description":"Don't allow breaking blocks next to liquids. Enable if you have mods adding custom fluid physics.","descriptionRu":"Включает или отключает функцию: «strict» «liquid» «check»."},{"name":"allowWaterBucketFall","type":"Boolean","defaultValue":"true","category":"Безопасность","description":"Allow Baritone to fall arbitrary distances and place a water bucket beneath it. Reliability: questionable.","descriptionRu":"Разрешает или запрещает использование воды ведра падения."},{"name":"assumeWalkOnWater","type":"Boolean","defaultValue":"false","category":"Безопасность","description":"Allow Baritone to assume it can walk on still water just like any other block. This functionality is assumed to be provided by a separate library that might have imported Baritone. Note: This will prevent some usage of the frostwalker enchantment, like pillaring up from water.","descriptionRu":"Учитывает ходьбы «on» воды при расчёте маршрута."},{"name":"assumeWalkOnLava","type":"Boolean","defaultValue":"false","category":"Безопасность","description":"If you have Fire Resistance and Jesus then I guess you could turn this on lol","descriptionRu":"Учитывает ходьбы «on» лавы при расчёте маршрута."},{"name":"assumeStep","type":"Boolean","defaultValue":"false","category":"Прочее","description":"Assume step functionality; don't jump on an Ascend.","descriptionRu":"Учитывает «step» при расчёте маршрута."},{"name":"assumeSafeWalk","type":"Boolean","defaultValue":"false","category":"Безопасность","description":"Assume safe walk functionality; don't sneak on a backplace traverse. Warning: if you do something janky like sneak-backplace from an ender chest, if this is true it won't sneak right click, it'll just right click, which means it'll open the chest instead of placing against it. That's why this defaults to off.","descriptionRu":"Учитывает безопасного режима ходьбы при расчёте маршрута."},{"name":"allowJumpAtBuildLimit","type":"Boolean","defaultValue":"false","category":"Строительство","description":"If true, parkour is allowed to make jumps when standing on blocks at the maximum height, so player feet is y=256 Defaults to false because this fails on constantiam. Please let me know if this is ever disabled. Please.","descriptionRu":"Разрешает или запрещает использование прыжка «at» строительства «limit»."},{"name":"allowParkourAscend","type":"Boolean","defaultValue":"true","category":"Передвижение","description":"This should be monetized it's so good Defaults to true, but only actually takes effect if allowParkour is also true","descriptionRu":"Разрешает или запрещает использование паркура подъёма."},{"name":"allowDiagonalDescend","type":"Boolean","defaultValue":"false","category":"Передвижение","description":"Allow descending diagonally Safer than allowParkour yet still slightly unsafe, can make contact with unchecked adjacent blocks, so it's unsafe in the nether. For a generic \"take some risks\" mode I'd turn on this one, parkour, and parkour place.","descriptionRu":"Разрешает или запрещает использование диагонального движения спуска."},{"name":"allowDiagonalAscend","type":"Boolean","defaultValue":"false","category":"Передвижение","description":"Allow diagonal ascending Actually pretty safe, much safer than diagonal descend tbh","descriptionRu":"Разрешает или запрещает использование диагонального движения подъёма."},{"name":"allowDownward","type":"Boolean","defaultValue":"true","category":"Передвижение","description":"Allow mining the block directly beneath its feet Turn this off to force it to make more staircases and less shafts","descriptionRu":"Разрешает или запрещает использование движения вниз."},{"name":"acceptableThrowawayItems","type":"List<Item>","defaultValue":"","category":"Инвентарь","description":"Blocks that Baritone is allowed to place (as throwaway, for sneak bridging, pillaring, etc.)","descriptionRu":"Настраивает параметр: «acceptable» «throwaway» предметов. Раздел: Инвентарь."},{"name":"blocksToAvoid","type":"List<Block>","defaultValue":"","category":"Безопасность","description":"Blocks that Baritone will attempt to avoid (Used in avoidance)","descriptionRu":"Настраивает параметр: блоков «to» избегания. Раздел: Безопасность."},{"name":"blocksToDisallowBreaking","type":"List<Block>","defaultValue":"","category":"Передвижение","description":"Blocks that Baritone is not allowed to break","descriptionRu":"Настраивает параметр: блоков «to» «disallow» разрушения. Раздел: Передвижение."},{"name":"blocksToAvoidBreaking","type":"List<Block>","defaultValue":"","category":"Безопасность","description":"blocks that baritone shouldn't break, but can if it needs to.","descriptionRu":"Настраивает параметр: блоков «to» избегания разрушения. Раздел: Безопасность."},{"name":"avoidBreakingMultiplier","type":"Double","defaultValue":"","category":"Безопасность","description":"this multiplies the break speed, if set above 1 it's \"encourage breaking\" instead","descriptionRu":"Настраивает стоимость или приоритет: избегания разрушения «multiplier»."},{"name":"buildIgnoreBlocks","type":"List<Block>","defaultValue":"","category":"Строительство","description":"A list of blocks to be treated as if they're air. If a schematic asks for air at a certain position, and that position currently contains a block on this list, it will be treated as correct.","descriptionRu":"Настраивает параметр: строительства игнорирования блоков. Раздел: Строительство."},{"name":"buildSkipBlocks","type":"List<Block>","defaultValue":"","category":"Строительство","description":"A list of blocks to be treated as correct. If a schematic asks for any block on this list at a certain position, it will be treated as correct, regardless of what it currently is.","descriptionRu":"Настраивает параметр: строительства «skip» блоков. Раздел: Строительство."},{"name":"buildValidSubstitutes","type":"Map<Block, List<Block>>","defaultValue":"","category":"Строительство","description":"A mapping of blocks to blocks treated as correct in their position If a schematic asks for a block on this mapping, all blocks on the mapped list will be accepted at that location as well Syntax same as  buildSubstitutes","descriptionRu":"Настраивает параметр: строительства «valid» «substitutes». Раздел: Строительство."},{"name":"buildSubstitutes","type":"Map<Block, List<Block>>","defaultValue":"","category":"Строительство","description":"A mapping of blocks to blocks to be built instead If a schematic asks for a block on this mapping, Baritone will place the first placeable block in the mapped list Usage Syntax: sourceblockA->blockToSubstituteA1,blockToSubstituteA2,...blockToSubstituteAN,sourceBlockB->blockToSubstituteB1,blockToSubstituteB2,...blockToSubstituteBN,...sourceBlockX->blockToSubstituteX1,blockToSubstituteX2...blockToSubstituteXN Example: stone->cobblestone,andesite,oak_planks->birch_planks,acacia_planks,glass","descriptionRu":"Настраивает параметр: строительства «substitutes». Раздел: Строительство."},{"name":"okIfAir","type":"List<Block>","defaultValue":"","category":"Прочее","description":"A list of blocks to become air If a schematic asks for a block on this list, only air will be accepted at that location (and nothing on buildIgnoreBlocks)","descriptionRu":"Настраивает параметр: «ok» «if» «air». Раздел: Прочее."},{"name":"buildIgnoreExisting","type":"Boolean","defaultValue":"false","category":"Строительство","description":"If this is true, the builder will treat all non-air blocks as correct. It will only place new blocks.","descriptionRu":"Включает или отключает функцию: строительства игнорирования «existing»."},{"name":"buildIgnoreDirection","type":"Boolean","defaultValue":"false","category":"Строительство","description":"If this is true, the builder will ignore directionality of certain blocks like glazed terracotta.","descriptionRu":"Включает или отключает функцию: строительства игнорирования «direction»."},{"name":"buildIgnoreProperties","type":"List<String>","defaultValue":"","category":"Строительство","description":"A list of names of block properties the builder will ignore.","descriptionRu":"Настраивает параметр: строительства игнорирования «properties». Раздел: Строительство."},{"name":"avoidUpdatingFallingBlocks","type":"Boolean","defaultValue":"true","category":"Безопасность","description":"If this setting is true, Baritone will never break a block that is adjacent to an unsupported falling block. I.E. it will never trigger cascading sand / gravel falls","descriptionRu":"Включает или отключает функцию: избегания «updating» «falling» блоков."},{"name":"allowVines","type":"Boolean","defaultValue":"false","category":"Передвижение","description":"Enables some more advanced vine features. They're honestly just gimmicks and won't ever be needed in real pathing scenarios. And they can cause Baritone to get trapped indefinitely in a strange scenario. Almost never turn this on lol","descriptionRu":"Разрешает или запрещает использование «vines»."},{"name":"allowWalkOnBottomSlab","type":"Boolean","defaultValue":"true","category":"Передвижение","description":"Slab behavior is complicated, disable this for higher path reliability. Leave enabled if you have bottom slabs everywhere in your base.","descriptionRu":"Разрешает или запрещает использование ходьбы «on» «bottom» «slab»."},{"name":"allowParkour","type":"Boolean","defaultValue":"false","category":"Передвижение","description":"You know what it is But it's very unreliable and falls off when cornering like all the time so. It also overshoots the landing pretty much always (making contact with the next block over), so be careful","descriptionRu":"Разрешает или запрещает использование паркура."},{"name":"allowParkourPlace","type":"Boolean","defaultValue":"false","category":"Передвижение","description":"Actually pretty reliable. Doesn't make it any more dangerous compared to just normal allowParkour th","descriptionRu":"Разрешает или запрещает использование паркура установки блоков."},{"name":"considerPotionEffects","type":"Boolean","defaultValue":"true","category":"Прочее","description":"For example, if you have Mining Fatigue or Haste, adjust the costs of breaking blocks accordingly.","descriptionRu":"Включает или отключает функцию: «consider» «potion» «effects»."},{"name":"sprintAscends","type":"Boolean","defaultValue":"true","category":"Передвижение","description":"Sprint and jump a block early on ascends wherever possible","descriptionRu":"Включает или отключает функцию: бега «ascends»."},{"name":"overshootTraverse","type":"Boolean","defaultValue":"true","category":"Прочее","description":"If we overshoot a traverse and end up one block beyond the destination, mark it as successful anyway. This helps with speed exceeding 20m/s","descriptionRu":"Включает или отключает функцию: «overshoot» «traverse»."},{"name":"pauseMiningForFallingBlocks","type":"Boolean","defaultValue":"true","category":"Безопасность","description":"When breaking blocks for a movement, wait until all falling blocks have settled before continuing","descriptionRu":"Включает или отключает функцию: «pause» добычи «for» «falling» блоков."},{"name":"rightClickSpeed","type":"Integer","defaultValue":"4","category":"Прочее","description":"How many ticks between right clicks are allowed. Default in game is 4","descriptionRu":"Настраивает параметр: «right» «click» скорости. Раздел: Прочее."},{"name":"randomLooking113","type":"Double","defaultValue":"2","category":"Прочее","description":"How many degrees to randomize the yaw every tick. Set to 0 to disable","descriptionRu":"Настраивает параметр: «random» «looking113». Раздел: Прочее."},{"name":"blockReachDistance","type":"Float","defaultValue":"4.5","category":"Прочее","description":"Block reach distance","descriptionRu":"Задаёт числовое ограничение: блока «reach» расстояния."},{"name":"blockBreakSpeed","type":"Integer","defaultValue":"6","category":"Прочее","description":"How many ticks between breaking a block and starting to break the next block. Default in game is 6 ticks. Values under 1 will be clamped. The delay only applies to non-instant (1-tick) breaks.","descriptionRu":"Настраивает параметр: блока разрушения скорости. Раздел: Прочее."},{"name":"randomLooking","type":"Double","defaultValue":"0.01","category":"Прочее","description":"How many degrees to randomize the pitch and yaw every tick. Set to 0 to disable","descriptionRu":"Настраивает параметр: «random» «looking». Раздел: Прочее."},{"name":"costHeuristic","type":"Double","defaultValue":"3.563","category":"Поиск пути","description":"This is the big A* setting. As long as your cost heuristic is an *underestimate*, it's guaranteed to find you the best path. 3.5 is always an underestimate, even if you are sprinting. If you're walking only (with allowSprint off) 4.6 is safe. Any value below 3.5 is never worth it. It's just more computation to find the same path, guaranteed. (specifically, it needs to be strictly slightly less than ActionCosts.WALK_ONE_BLOCK_COST, which is about 3.56) Setting it at 3.57 or above with sprinting, or to 4.64 or above without sprinting, will result in faster computation, at the cost of a suboptimal path. Any value above the walk / sprint cost will result in it going straight at its goal, and not investigating alternatives, because the combined cost / heuristic metric gets better and better with each block, instead of slightly worse. Finding the optimal path is worth it, so it's the default.","descriptionRu":"Настраивает параметр: стоимости «heuristic». Раздел: Поиск пути."},{"name":"pathingMaxChunkBorderFetch","type":"Integer","defaultValue":"50","category":"Поиск пути","description":"The maximum number of times it will fetch outside loaded or cached chunks before assuming that pathing has reached the end of the known area, and should therefore stop.","descriptionRu":"Настраивает параметр: «pathing» максимального чанка «border» «fetch». Раздел: Поиск пути."},{"name":"backtrackCostFavoringCoefficient","type":"Double","defaultValue":"0.5","category":"Поиск пути","description":"Set to 1.0 to effectively disable this feature","descriptionRu":"Настраивает стоимость или приоритет: «backtrack» стоимости «favoring» «coefficient»."},{"name":"avoidance","type":"Boolean","defaultValue":"false","category":"Безопасность","description":"Toggle the following 4 settings They have a noticeable performance impact, so they default off Specifically, building up the avoidance map on the main thread before pathing starts actually takes a noticeable amount of time, especially when there are a lot of mobs around, and your game jitters for like 200ms while doing so","descriptionRu":"Включает или отключает функцию: избегания."},{"name":"mobSpawnerAvoidanceCoefficient","type":"Double","defaultValue":"2.0","category":"Безопасность","description":"Set to 1.0 to effectively disable this feature Set below 1.0 to go out of your way to walk near mob spawners","descriptionRu":"Настраивает стоимость или приоритет: мобов «spawner» избегания «coefficient»."},{"name":"mobSpawnerAvoidanceRadius","type":"Integer","defaultValue":"16","category":"Безопасность","description":"Distance to avoid mob spawners.","descriptionRu":"Задаёт числовое ограничение: мобов «spawner» избегания радиуса."},{"name":"mobAvoidanceCoefficient","type":"Double","defaultValue":"1.5","category":"Безопасность","description":"Set to 1.0 to effectively disable this feature Set below 1.0 to go out of your way to walk near mobs","descriptionRu":"Настраивает стоимость или приоритет: мобов избегания «coefficient»."},{"name":"mobAvoidanceRadius","type":"Integer","defaultValue":"8","category":"Безопасность","description":"Distance to avoid mobs.","descriptionRu":"Задаёт числовое ограничение: мобов избегания радиуса."},{"name":"rightClickContainerOnArrival","type":"Boolean","defaultValue":"true","category":"Прочее","description":"When running a goto towards a container block (chest, ender chest, furnace, etc), right click and open it once you arrive.","descriptionRu":"Включает или отключает функцию: «right» «click» «container» «on» «arrival»."},{"name":"enterPortal","type":"Boolean","defaultValue":"true","category":"Прочее","description":"When running a goto towards a nether portal block, walk all the way into the portal instead of stopping one block before.","descriptionRu":"Включает или отключает функцию: «enter» «portal»."},{"name":"minimumImprovementRepropagation","type":"Boolean","defaultValue":"true","category":"Прочее","description":"Don't repropagate cost improvements below 0.01 ticks. They're all just floating point inaccuracies, and there's no point.","descriptionRu":"Включает или отключает функцию: «minimum» «improvement» «repropagation»."},{"name":"cutoffAtLoadBoundary","type":"Boolean","defaultValue":"false","category":"Прочее","description":"After calculating a path (potentially through cached chunks), artificially cut it off to just the part that is entirely within currently loaded chunks. Improves path safety because cached chunks are heavily simplified. This is much safer to leave off now, and makes pathing more efficient. More explanation in the issue.","descriptionRu":"Включает или отключает функцию: «cutoff» «at» «load» «boundary»."},{"name":"maxCostIncrease","type":"Double","defaultValue":"10","category":"Поиск пути","description":"If a movement's cost increases by more than this amount between calculation and execution (due to changes in the environment / world), cancel and recalculate","descriptionRu":"Настраивает стоимость или приоритет: максимального стоимости «increase»."},{"name":"costVerificationLookahead","type":"Integer","defaultValue":"5","category":"Поиск пути","description":"Stop 5 movements before anything that made the path COST_INF. For example, if lava has spread across the path, don't walk right up to it then recalculate, it might still be spreading lol","descriptionRu":"Настраивает параметр: стоимости «verification» «lookahead». Раздел: Поиск пути."},{"name":"pathCutoffFactor","type":"Double","defaultValue":"0.9","category":"Поиск пути","description":"Static cutoff factor. 0.9 means cut off the last 10% of all paths, regardless of chunk load state","descriptionRu":"Задаёт числовое ограничение: маршрута «cutoff» «factor»."},{"name":"pathCutoffMinimumLength","type":"Integer","defaultValue":"30","category":"Поиск пути","description":"Only apply static cutoff for paths of at least this length (in terms of number of movements)","descriptionRu":"Задаёт числовое ограничение: маршрута «cutoff» «minimum» «length»."},{"name":"planningTickLookahead","type":"Integer","defaultValue":"150","category":"Прочее","description":"Start planning the next path once the remaining movements tick estimates sum up to less than this value","descriptionRu":"Настраивает параметр: «planning» «tick» «lookahead». Раздел: Прочее."},{"name":"pathingMapDefaultSize","type":"Integer","defaultValue":"1024","category":"Поиск пути","description":"Default size of the Long2ObjectOpenHashMap used in pathing","descriptionRu":"Задаёт числовое ограничение: «pathing» «map» «default» размера."},{"name":"pathingMapLoadFactor","type":"Float","defaultValue":"0.75","category":"Поиск пути","description":"Load factor coefficient for the Long2ObjectOpenHashMap used in pathing Decrease for faster map operations, but higher memory usage","descriptionRu":"Настраивает параметр: «pathing» «map» «load» «factor». Раздел: Поиск пути."},{"name":"maxFallHeightNoWater","type":"Integer","defaultValue":"3","category":"Безопасность","description":"How far are you allowed to fall onto solid ground (without a water bucket)? 3 won't deal any damage. But if you just want to get down the mountain quickly and you have Feather Falling IV, you might set it a bit higher, like 4 or 5.","descriptionRu":"Задаёт числовое ограничение: максимального падения высоты «no» воды."},{"name":"maxFallHeightBucket","type":"Integer","defaultValue":"20","category":"Безопасность","description":"How far are you allowed to fall onto solid ground (with a water bucket)? It's not that reliable, so I've set it below what would kill an unarmored player (23)","descriptionRu":"Задаёт числовое ограничение: максимального падения высоты ведра."},{"name":"allowOvershootDiagonalDescend","type":"Boolean","defaultValue":"true","category":"Передвижение","description":"Is it okay to sprint through a descend followed by a diagonal? The player overshoots the landing, but not enough to fall off. And the diagonal ensures that there isn't lava or anything that's !canWalkInto in that space, so it's technically safe, just a little sketchy. Note: this is *not* related to the allowDiagonalDescend setting, that is a completely different thing.","descriptionRu":"Разрешает или запрещает использование «overshoot» диагонального движения спуска."},{"name":"simplifyUnloadedYCoord","type":"Boolean","defaultValue":"true","category":"Прочее","description":"If your goal is a GoalBlock in an unloaded chunk, assume it's far enough away that the Y coord doesn't matter yet, and replace it with a GoalXZ to the same place before calculating a path. Once a segment ends within chunk load range of the GoalBlock, it will go back to normal behavior of considering the Y coord. The reasoning is that if your X and Z are 10,000 blocks away, your Y coordinate's accuracy doesn't matter at all until you get much much closer.","descriptionRu":"Включает или отключает функцию: «simplify» «unloaded» «ycoord»."},{"name":"repackOnAnyBlockChange","type":"Boolean","defaultValue":"true","category":"Прочее","description":"Whenever a block changes, repack the whole chunk that it's in","descriptionRu":"Включает или отключает функцию: «repack» «on» «any» блока «change»."},{"name":"movementTimeoutTicks","type":"Integer","defaultValue":"100","category":"Поиск пути","description":"If a movement takes this many ticks more than its initial cost estimate, cancel it","descriptionRu":"Задаёт временной параметр: «movement» тайм-аута тиков."},{"name":"primaryTimeoutMS","type":"Long","defaultValue":"500","category":"Поиск пути","description":"Pathing ends after this amount of time, but only if a path has been found If no valid path (length above the minimum) has been found, pathing continues up until the failure timeout","descriptionRu":"Задаёт временной параметр: «primary» тайм-аута «ms»."},{"name":"failureTimeoutMS","type":"Long","defaultValue":"2000","category":"Поиск пути","description":"Pathing can never take longer than this, even if that means failing to find any path at all","descriptionRu":"Задаёт временной параметр: «failure» тайм-аута «ms»."},{"name":"planAheadPrimaryTimeoutMS","type":"Long","defaultValue":"4000","category":"Поиск пути","description":"Planning ahead while executing a segment ends after this amount of time, but only if a path has been found If no valid path (length above the minimum) has been found, pathing continues up until the failure timeout","descriptionRu":"Задаёт временной параметр: «plan» «ahead» «primary» тайм-аута «ms»."},{"name":"planAheadFailureTimeoutMS","type":"Long","defaultValue":"5000","category":"Поиск пути","description":"Planning ahead while executing a segment can never take longer than this, even if that means failing to find any path at all","descriptionRu":"Задаёт временной параметр: «plan» «ahead» «failure» тайм-аута «ms»."},{"name":"slowPath","type":"Boolean","defaultValue":"false","category":"Поиск пути","description":"For debugging, consider nodes much much slower","descriptionRu":"Включает или отключает функцию: «slow» маршрута."},{"name":"slowPathTimeDelayMS","type":"Long","defaultValue":"100","category":"Поиск пути","description":"Milliseconds between each node","descriptionRu":"Задаёт временной параметр: «slow» маршрута «time» задержки «ms»."},{"name":"slowPathTimeoutMS","type":"Long","defaultValue":"40000","category":"Поиск пути","description":"The alternative timeout number when slowPath is on","descriptionRu":"Задаёт временной параметр: «slow» маршрута тайм-аута «ms»."},{"name":"doBedWaypoints","type":"Boolean","defaultValue":"true","category":"Прочее","description":"allows baritone to save bed waypoints when interacting with beds","descriptionRu":"Включает или отключает функцию: «do» «bed» «waypoints»."},{"name":"doDeathWaypoints","type":"Boolean","defaultValue":"true","category":"Прочее","description":"allows baritone to save death waypoints","descriptionRu":"Включает или отключает функцию: «do» «death» «waypoints»."},{"name":"chunkCaching","type":"Boolean","defaultValue":"true","category":"Поиск пути","description":"The big one. Download all chunks in simplified 2-bit format and save them for better very-long-distance pathing.","descriptionRu":"Включает или отключает функцию: чанка «caching»."},{"name":"pruneRegionsFromRAM","type":"Boolean","defaultValue":"true","category":"Прочее","description":"On save, delete from RAM any cached regions that are more than 1024 blocks away from the player Temporarily disabled Temporarily reenabled","descriptionRu":"Включает или отключает функцию: «prune» «regions» «from» «ram»."},{"name":"chunkPackerQueueMaxSize","type":"Integer","defaultValue":"2000","category":"Поиск пути","description":"The chunk packer queue can never grow to larger than this, if it does, the oldest chunks are discarded The newest chunks are kept, so that if you're moving in a straight line quickly then stop, your immediate render distance is still included","descriptionRu":"Задаёт числовое ограничение: чанка «packer» «queue» максимального размера."},{"name":"backfill","type":"Boolean","defaultValue":"false","category":"Прочее","description":"Fill in blocks behind you","descriptionRu":"Включает или отключает функцию: «backfill»."},{"name":"logAsToast","type":"Boolean","defaultValue":"false","category":"Чат и команды","description":"Shows popup message in the upper right corner, similarly to when you make an advancement","descriptionRu":"Включает или отключает функцию: «log» «as» «toast»."},{"name":"chatDebug","type":"Boolean","defaultValue":"false","category":"Чат и команды","description":"Print all the debug messages to chat","descriptionRu":"Включает или отключает функцию: чата «debug»."},{"name":"chatControl","type":"Boolean","defaultValue":"true","category":"Чат и команды","description":"Allow chat based control of Baritone. Most likely should be disabled when Baritone is imported for use in something else","descriptionRu":"Включает или отключает функцию: чата управления."},{"name":"chatControlAnyway","type":"Boolean","defaultValue":"false","category":"Чат и команды","description":"Some clients like Impact try to force chatControl to off, so here's a second setting to do it anyway","descriptionRu":"Включает или отключает функцию: чата управления «anyway»."},{"name":"renderPath","type":"Boolean","defaultValue":"true","category":"Отображение","description":"Render the path","descriptionRu":"Управляет отображением маршрута в игре."},{"name":"renderPathAsLine","type":"Boolean","defaultValue":"false","category":"Отображение","description":"Render the path as a line instead of a frickin thingy","descriptionRu":"Управляет отображением маршрута «as» «line» в игре."},{"name":"renderGoal","type":"Boolean","defaultValue":"true","category":"Отображение","description":"Render the goal","descriptionRu":"Управляет отображением цели в игре."},{"name":"renderGoalAnimated","type":"Boolean","defaultValue":"true","category":"Отображение","description":"Render the goal as a sick animated thingy instead of just a box (also controls animation of GoalXZ if {@link #renderGoalXZBeacon} is enabled)","descriptionRu":"Управляет отображением цели «animated» в игре."},{"name":"renderSelectionBoxes","type":"Boolean","defaultValue":"true","category":"Отображение","description":"Render selection boxes","descriptionRu":"Управляет отображением выделения «boxes» в игре."},{"name":"renderGoalIgnoreDepth","type":"Boolean","defaultValue":"true","category":"Отображение","description":"Ignore depth when rendering the goal","descriptionRu":"Управляет отображением цели игнорирования «depth» в игре."},{"name":"renderGoalXZBeacon","type":"Boolean","defaultValue":"false","category":"Отображение","description":"Renders X/Z type Goals with the vanilla beacon beam effect. Combining this with {@link #renderGoalIgnoreDepth} will cause strange render clipping.","descriptionRu":"Управляет отображением цели «xzbeacon» в игре."},{"name":"renderSelectionBoxesIgnoreDepth","type":"Boolean","defaultValue":"true","category":"Отображение","description":"Ignore depth when rendering the selection boxes (to break, to place, to walk into)","descriptionRu":"Управляет отображением выделения «boxes» игнорирования «depth» в игре."},{"name":"renderPathIgnoreDepth","type":"Boolean","defaultValue":"true","category":"Отображение","description":"Ignore depth when rendering the path","descriptionRu":"Управляет отображением маршрута игнорирования «depth» в игре."},{"name":"pathRenderLineWidthPixels","type":"Float","defaultValue":"5","category":"Отображение","description":"Line width of the path when rendered, in pixels","descriptionRu":"Задаёт числовое ограничение: маршрута отображение «line» ширины «pixels»."},{"name":"goalRenderLineWidthPixels","type":"Float","defaultValue":"3","category":"Отображение","description":"Line width of the goal when rendered, in pixels","descriptionRu":"Задаёт числовое ограничение: цели отображение «line» ширины «pixels»."},{"name":"fadePath","type":"Boolean","defaultValue":"false","category":"Отображение","description":"Start fading out the path at 20 movements ahead, and stop rendering it entirely 30 movements ahead. Improves FPS.","descriptionRu":"Включает или отключает функцию: «fade» маршрута."},{"name":"freeLook","type":"Boolean","defaultValue":"true","category":"Прочее","description":"Move without having to force the client-sided rotations","descriptionRu":"Включает или отключает функцию: «free» взгляда."},{"name":"blockFreeLook","type":"Boolean","defaultValue":"false","category":"Прочее","description":"Break and place blocks without having to force the client-sided rotations. Requires {@link #freeLook}.","descriptionRu":"Включает или отключает функцию: блока «free» взгляда."},{"name":"elytraFreeLook","type":"Boolean","defaultValue":"true","category":"Элитры","description":"Automatically elytra fly without having to force the client-sided rotations.","descriptionRu":"Включает или отключает функцию: элитр «free» взгляда."},{"name":"smoothLook","type":"Boolean","defaultValue":"false","category":"Прочее","description":"Forces the client-sided yaw rotation to an average of the last {@link #smoothLookTicks} of server-sided rotations.","descriptionRu":"Включает или отключает функцию: «smooth» взгляда."},{"name":"elytraSmoothLook","type":"Boolean","defaultValue":"false","category":"Элитры","description":"Same as {@link #smoothLook} but for elytra flying.","descriptionRu":"Включает или отключает функцию: элитр «smooth» взгляда."},{"name":"smoothLookTicks","type":"Integer","defaultValue":"5","category":"Прочее","description":"The number of ticks to average across for {@link #smoothLook};","descriptionRu":"Задаёт временной параметр: «smooth» взгляда тиков."},{"name":"remainWithExistingLookDirection","type":"Boolean","defaultValue":"true","category":"Прочее","description":"When true, the player will remain with its existing look direction as often as possible. Although, in some cases this can get it stuck, hence this setting to disable that behavior.","descriptionRu":"Включает или отключает функцию: «remain» «with» «existing» взгляда «direction»."},{"name":"antiCheatCompatibility","type":"Boolean","defaultValue":"true","category":"Прочее","description":"Will cause some minor behavioral differences to ensure that Baritone works on anticheats. At the moment this will silently set the player's rotations when using freeLook so you're not sprinting in directions other than forward, which is picken up by more \"advanced\" anticheats like AAC, but not NCP.","descriptionRu":"Включает или отключает функцию: «anti» «cheat» «compatibility»."},{"name":"pathThroughCachedOnly","type":"Boolean","defaultValue":"false","category":"Поиск пути","description":"Exclusively use cached chunks for pathing Never turn this on","descriptionRu":"Включает или отключает функцию: маршрута «through» «cached» «only»."},{"name":"sprintInWater","type":"Boolean","defaultValue":"true","category":"Безопасность","description":"Continue sprinting while in water","descriptionRu":"Включает или отключает функцию: бега «in» воды."},{"name":"blacklistClosestOnFailure","type":"Boolean","defaultValue":"true","category":"Прочее","description":"When GetToBlockProcess or MineProcess fails to calculate a path, instead of just giving up, mark the closest instance of that block as \"unreachable\" and go towards the next closest. GetToBlock expands this search to the whole \"vein\"; MineProcess does not. This is because MineProcess finds individual impossible blocks (like one block in a vein that has gravel on top then lava, so it can't break) Whereas GetToBlock should blacklist the whole \"vein\" if it can't get to any of them.","descriptionRu":"Включает или отключает функцию: «blacklist» «closest» «on» «failure»."},{"name":"renderCachedChunks","type":"Boolean","defaultValue":"false","category":"Отображение","description":"😎 Render cached chunks as semitransparent. Doesn't work with OptiFine 😭 Rarely randomly crashes, see  this issue . Can be very useful on servers with low render distance. After enabling, you may need to reload the world in order for it to have an effect (e.g. disconnect and reconnect, enter then exit the nether, die and respawn, etc). This may literally kill your FPS and CPU because every chunk gets recompiled twice as much as normal, since the cached version comes into range, then the normal one comes from the server for real. Note that flowing water is cached as AVOID, which is rendered as lava. As you get closer, you may therefore see lava falls being replaced with water falls. SOLID is rendered as stone in the overworld, netherrack in the nether, and end stone in the end","descriptionRu":"Управляет отображением «cached» «chunks» в игре."},{"name":"cachedChunksOpacity","type":"Float","defaultValue":"0.5","category":"Отображение","description":"0.0f = not visible, fully transparent (instead of setting this to 0, turn off renderCachedChunks) 1.0f = fully opaque","descriptionRu":"Настраивает параметр: «cached» «chunks» прозрачности. Раздел: Отображение."},{"name":"prefixControl","type":"Boolean","defaultValue":"true","category":"Чат и команды","description":"Whether or not to allow you to run Baritone commands with the prefix","descriptionRu":"Включает или отключает функцию: префикса управления."},{"name":"prefix","type":"String","defaultValue":"#","category":"Чат и команды","description":"The command prefix for chat control","descriptionRu":"Настраивает параметр: префикса. Раздел: Чат и команды."},{"name":"shortBaritonePrefix","type":"Boolean","defaultValue":"false","category":"Чат и команды","description":"Use a short Baritone prefix [B] instead of [Baritone] when logging to chat","descriptionRu":"Включает или отключает функцию: «short» «baritone» префикса."},{"name":"useMessageTag","type":"Boolean","defaultValue":"false","category":"Прочее","description":"Use a modern message tag instead of a prefix when logging to chat","descriptionRu":"Включает или отключает функцию: «use» «message» «tag»."},{"name":"echoCommands","type":"Boolean","defaultValue":"true","category":"Чат и команды","description":"Echo commands to chat when they are run","descriptionRu":"Включает или отключает функцию: «echo» команд."},{"name":"censorCoordinates","type":"Boolean","defaultValue":"false","category":"Прочее","description":"Censor coordinates in goals and block positions","descriptionRu":"Включает или отключает функцию: «censor» «coordinates»."},{"name":"censorRanCommands","type":"Boolean","defaultValue":"false","category":"Чат и команды","description":"Censor arguments to ran commands, to hide, for example, coordinates to #goal","descriptionRu":"Включает или отключает функцию: «censor» «ran» команд."},{"name":"itemSaver","type":"Boolean","defaultValue":"false","category":"Прочее","description":"Stop using tools just before they are going to break.","descriptionRu":"Включает или отключает функцию: «item» «saver»."},{"name":"itemSaverThreshold","type":"Integer","defaultValue":"10","category":"Прочее","description":"Durability to leave on the tool when using itemSaver","descriptionRu":"Задаёт числовое ограничение: «item» «saver» «threshold»."},{"name":"preferSilkTouch","type":"Boolean","defaultValue":"false","category":"Прочее","description":"Always prefer silk touch tools over regular tools. This will not sacrifice speed, but it will always prefer silk touch tools over other tools of the same speed. This includes always choosing ANY silk touch tool over your hand.","descriptionRu":"Включает или отключает функцию: «prefer» «silk» «touch»."},{"name":"walkWhileBreaking","type":"Boolean","defaultValue":"true","category":"Передвижение","description":"Don't stop walking forward when you need to break blocks in your way","descriptionRu":"Включает или отключает функцию: ходьбы «while» разрушения."},{"name":"splicePath","type":"Boolean","defaultValue":"true","category":"Поиск пути","description":"When a new segment is calculated that doesn't overlap with the current one, but simply begins where the current segment ends, splice it on and make a longer combined path. If this setting is off, any planned segment will not be spliced and will instead be the \"next path\" in PathingBehavior, and will only start after this one ends. Turning this off hurts planning ahead, because the next segment will exist even if it's very short.","descriptionRu":"Включает или отключает функцию: «splice» маршрута."},{"name":"maxPathHistoryLength","type":"Integer","defaultValue":"300","category":"Поиск пути","description":"If we are more than 300 movements into the current path, discard the oldest segments, as they are no longer useful","descriptionRu":"Задаёт числовое ограничение: максимального маршрута «history» «length»."},{"name":"pathHistoryCutoffAmount","type":"Integer","defaultValue":"50","category":"Поиск пути","description":"If the current path is too long, cut off this many movements from the beginning.","descriptionRu":"Задаёт числовое ограничение: маршрута «history» «cutoff» «amount»."},{"name":"mineGoalUpdateInterval","type":"Integer","defaultValue":"5","category":"Добыча и поиск","description":"Rescan for the goal once every 5 ticks. Set to 0 to disable.","descriptionRu":"Настраивает параметр: добычи цели «update» «interval». Раздел: Добыча и поиск."},{"name":"maxCachedWorldScanCount","type":"Integer","defaultValue":"10","category":"Добыча и поиск","description":"After finding this many instances of the target block in the cache, it will stop expanding outward the chunk search.","descriptionRu":"Задаёт числовое ограничение: максимального «cached» мира сканирования количества."},{"name":"mineMaxOreLocationsCount","type":"Integer","defaultValue":"64","category":"Добыча и поиск","description":"Mine will not scan for or remember more than this many target locations. Note that the number of locations retrieved from cache is additionaly limited by {@link #maxCachedWorldScanCount}.","descriptionRu":"Задаёт числовое ограничение: добычи максимального «ore» «locations» количества."},{"name":"minYLevelWhileMining","type":"Integer","defaultValue":"0","category":"Прочее","description":"Sets the minimum y level whilst mining - set to 0 to turn off. if world has negative y values, subtract the min world height to get the value to put here","descriptionRu":"Задаёт числовое ограничение: минимального «ylevel» «while» добычи."},{"name":"maxYLevelWhileMining","type":"Integer","defaultValue":"2031","category":"Прочее","description":"Sets the maximum y level to mine ores at.","descriptionRu":"Задаёт числовое ограничение: максимального «ylevel» «while» добычи."},{"name":"allowOnlyExposedOres","type":"Boolean","defaultValue":"false","category":"Добыча и поиск","description":"This will only allow baritone to mine exposed ores, can be used to stop ore obfuscators on servers that use them.","descriptionRu":"Разрешает или запрещает использование «only» «exposed» «ores»."},{"name":"allowOnlyExposedOresDistance","type":"Integer","defaultValue":"1","category":"Добыча и поиск","description":"When allowOnlyExposedOres is enabled this is the distance around to search. It is recommended to keep this value low, as it dramatically increases calculation times.","descriptionRu":"Разрешает или запрещает использование «only» «exposed» «ores» расстояния."},{"name":"exploreForBlocks","type":"Boolean","defaultValue":"true","category":"Добыча и поиск","description":"When GetToBlock or non-legit Mine doesn't know any locations for the desired block, explore randomly instead of giving up.","descriptionRu":"Включает или отключает функцию: исследования «for» блоков."},{"name":"worldExploringChunkOffset","type":"Integer","defaultValue":"0","category":"Поиск пути","description":"While exploring the world, offset the closest unloaded chunk by this much in both axes. This can result in more efficient loading, if you set this to the render distance.","descriptionRu":"Настраивает параметр: мира «exploring» чанка смещения. Раздел: Поиск пути."},{"name":"exploreChunkSetMinimumSize","type":"Integer","defaultValue":"10","category":"Добыча и поиск","description":"Take the 10 closest chunks, even if they aren't strictly tied for distance metric from origin.","descriptionRu":"Задаёт числовое ограничение: исследования чанка «set» «minimum» размера."},{"name":"exploreMaintainY","type":"Integer","defaultValue":"64","category":"Добыча и поиск","description":"Attempt to maintain Y coordinate while exploring -1 to disable","descriptionRu":"Настраивает параметр: исследования «maintain» «y». Раздел: Добыча и поиск."},{"name":"replantCrops","type":"Boolean","defaultValue":"true","category":"Прочее","description":"Replant normal Crops while farming and leave cactus and sugarcane to regrow","descriptionRu":"Включает или отключает функцию: «replant» «crops»."},{"name":"replantNetherWart","type":"Boolean","defaultValue":"false","category":"Прочее","description":"Replant nether wart while farming. This setting only has an effect when replantCrops is also enabled","descriptionRu":"Включает или отключает функцию: «replant» «nether» «wart»."},{"name":"farmMaxScanSize","type":"Integer","defaultValue":"256","category":"Добыча и поиск","description":"Farming will scan for at most this many blocks.","descriptionRu":"Задаёт числовое ограничение: фермы максимального сканирования размера."},{"name":"extendCacheOnThreshold","type":"Boolean","defaultValue":"false","category":"Поиск пути","description":"When the cache scan gives less blocks than the maximum threshold (but still above zero), scan the main world too. Only if you have a beefy CPU and automatically mine blocks that are in cache","descriptionRu":"Задаёт числовое ограничение: «extend» кэша «on» «threshold»."},{"name":"buildInLayers","type":"Boolean","defaultValue":"false","category":"Строительство","description":"Don't consider the next layer in builder until the current one is done","descriptionRu":"Включает или отключает функцию: строительства «in» «layers»."},{"name":"layerOrder","type":"Boolean","defaultValue":"false","category":"Строительство","description":"false = build from bottom to top true = build from top to bottom","descriptionRu":"Включает или отключает функцию: слоя «order»."},{"name":"layerHeight","type":"Integer","defaultValue":"1","category":"Строительство","description":"How high should the individual layers be?","descriptionRu":"Задаёт числовое ограничение: слоя высоты."},{"name":"startAtLayer","type":"Integer","defaultValue":"0","category":"Строительство","description":"Start building the schematic at a specific layer. Can help on larger builds when schematic wants to break things its already built","descriptionRu":"Настраивает параметр: «start» «at» слоя. Раздел: Строительство."},{"name":"skipFailedLayers","type":"Boolean","defaultValue":"false","category":"Строительство","description":"If a layer is unable to be constructed, just skip it.","descriptionRu":"Включает или отключает функцию: «skip» «failed» «layers»."},{"name":"buildOnlySelection","type":"Boolean","defaultValue":"false","category":"Строительство","description":"Only build the selected part of schematics","descriptionRu":"Включает или отключает функцию: строительства «only» выделения."},{"name":"buildRepeat","type":"Vec3i","defaultValue":"","category":"Строительство","description":"How far to move before repeating the build. 0 to disable repeating on a certain axis, 0,0,0 to disable entirely","descriptionRu":"Настраивает параметр: строительства повтора. Раздел: Строительство."},{"name":"buildRepeatCount","type":"Integer","defaultValue":"-1","category":"Строительство","description":"How many times to buildrepeat. -1 for infinite.","descriptionRu":"Задаёт числовое ограничение: строительства повтора количества."},{"name":"buildRepeatSneaky","type":"Boolean","defaultValue":"true","category":"Строительство","description":"Don't notify schematics that they are moved. e.g. replacing will replace the same spots for every repetition Mainly for backward compatibility.","descriptionRu":"Включает или отключает функцию: строительства повтора «sneaky»."},{"name":"breakFromAbove","type":"Boolean","defaultValue":"false","category":"Прочее","description":"Allow standing above a block while mining it, in BuilderProcess Experimental","descriptionRu":"Включает или отключает функцию: разрушения «from» «above»."},{"name":"goalBreakFromAbove","type":"Boolean","defaultValue":"false","category":"Прочее","description":"As well as breaking from above, set a goal to up and to the side of all blocks to break. Never turn this on without also turning on breakFromAbove.","descriptionRu":"Включает или отключает функцию: цели разрушения «from» «above»."},{"name":"mapArtMode","type":"Boolean","defaultValue":"false","category":"Строительство","description":"Build in map art mode, which makes baritone only care about the top block in each column","descriptionRu":"Включает или отключает функцию: «map» «art» «mode»."},{"name":"okIfWater","type":"Boolean","defaultValue":"false","category":"Безопасность","description":"Override builder's behavior to not attempt to correct blocks that are currently water","descriptionRu":"Включает или отключает функцию: «ok» «if» воды."},{"name":"incorrectSize","type":"Integer","defaultValue":"100","category":"Прочее","description":"The set of incorrect blocks can never grow beyond this size","descriptionRu":"Задаёт числовое ограничение: «incorrect» размера."},{"name":"breakCorrectBlockPenaltyMultiplier","type":"Double","defaultValue":"10","category":"Поиск пути","description":"Multiply the cost of breaking a block that's correct in the builder's schematic by this coefficient","descriptionRu":"Настраивает стоимость или приоритет: разрушения «correct» блока штрафа «multiplier»."},{"name":"placeIncorrectBlockPenaltyMultiplier","type":"Double","defaultValue":"2","category":"Поиск пути","description":"Multiply the cost of placing a block that's incorrect in the builder's schematic by this coefficient","descriptionRu":"Настраивает стоимость или приоритет: установки блоков «incorrect» блока штрафа «multiplier»."},{"name":"schematicOrientationX","type":"Boolean","defaultValue":"false","category":"Строительство","description":"When this setting is true, build a schematic with the highest X coordinate being the origin, instead of the lowest","descriptionRu":"Включает или отключает функцию: схемы «orientation» «x»."},{"name":"schematicOrientationY","type":"Boolean","defaultValue":"false","category":"Строительство","description":"When this setting is true, build a schematic with the highest Y coordinate being the origin, instead of the lowest","descriptionRu":"Включает или отключает функцию: схемы «orientation» «y»."},{"name":"schematicOrientationZ","type":"Boolean","defaultValue":"false","category":"Строительство","description":"When this setting is true, build a schematic with the highest Z coordinate being the origin, instead of the lowest","descriptionRu":"Включает или отключает функцию: схемы «orientation» «z»."},{"name":"buildSchematicRotation","type":"Rotation","defaultValue":"none","category":"Строительство","description":"Rotates the schematic before building it. Possible values are NONE - No rotation CLOCKWISE_90 - Rotate 90° clockwise CLOCKWISE_180 - Rotate 180° clockwise COUNTERCLOCKWISE_90 - Rotate 270° clockwise","descriptionRu":"Настраивает параметр: строительства схемы «rotation». Раздел: Строительство."},{"name":"buildSchematicMirror","type":"Mirror","defaultValue":"none","category":"Строительство","description":"Mirrors the schematic before building it. Possible values are FRONT_BACK - mirror the schematic along its local x axis LEFT_RIGHT - mirror the schematic along its local z axis","descriptionRu":"Настраивает параметр: строительства схемы «mirror». Раздел: Строительство."},{"name":"schematicFallbackExtension","type":"String","defaultValue":"schematic","category":"Строительство","description":"The fallback used by the build command when no extension is specified. This may be useful if schematics of a particular format are used often, and the user does not wish to have to specify the extension with every usage.","descriptionRu":"Настраивает параметр: схемы «fallback» «extension». Раздел: Строительство."},{"name":"builderTickScanRadius","type":"Integer","defaultValue":"5","category":"Строительство","description":"Distance to scan every tick for updates. Expanding this beyond player reach distance (i.e. setting it to 6 or above) is only necessary in very large schematics where rescanning the whole thing is costly.","descriptionRu":"Задаёт числовое ограничение: «builder» «tick» сканирования радиуса."},{"name":"mineScanDroppedItems","type":"Boolean","defaultValue":"true","category":"Добыча и поиск","description":"While mining, should it also consider dropped items of the correct type as a pathing destination (as well as ore blocks)?","descriptionRu":"Включает или отключает функцию: добычи сканирования «dropped» предметов."},{"name":"mineDropLoiterDurationMSThanksLouca","type":"Long","defaultValue":"250","category":"Добыча и поиск","description":"While mining, wait this number of milliseconds after mining an ore to see if it will drop an item instead of immediately going onto the next one Thanks Louca","descriptionRu":"Настраивает параметр: добычи «drop» «loiter» «duration» «msthanks» «louca». Раздел: Добыча и поиск."},{"name":"distanceTrim","type":"Boolean","defaultValue":"true","category":"Прочее","description":"Trim incorrect positions too far away, helps performance but hurts reliability in very large schematics","descriptionRu":"Включает или отключает функцию: расстояния «trim»."},{"name":"cancelOnGoalInvalidation","type":"Boolean","defaultValue":"true","category":"Прочее","description":"Cancel the current path if the goal has changed, and the path originally ended in the goal but doesn't anymore. Currently only runs when either MineBehavior or FollowBehavior is active. For example, if Baritone is doing \"mine iron_ore\", the instant it breaks the ore (and it becomes air), that location is no longer a goal. This means that if this setting is true, it will stop there. If this setting were off, it would continue with its path, and walk into that location. The tradeoff is if this setting is true, it mines ores much faster since it doesn't waste any time getting into locations that no longer contain ores, but on the other hand, it misses some drops, and continues on without ever picking them up. Also on cosmic prisons this should be set to true since you don't actually mine the ore it just gets replaced with stone.","descriptionRu":"Включает или отключает функцию: «cancel» «on» цели «invalidation»."},{"name":"axisHeight","type":"Integer","defaultValue":"120","category":"Прочее","description":"The \"axis\" command (aka GoalAxis) will go to a axis, or diagonal axis, at this Y level.","descriptionRu":"Задаёт числовое ограничение: «axis» высоты."},{"name":"disconnectOnArrival","type":"Boolean","defaultValue":"false","category":"Прочее","description":"Disconnect from the server upon arriving at your goal","descriptionRu":"Включает или отключает функцию: «disconnect» «on» «arrival»."},{"name":"legitMine","type":"Boolean","defaultValue":"false","category":"Добыча и поиск","description":"Disallow MineBehavior from using X-Ray to see where the ores are. Turn this option on to force it to mine \"legit\" where it will only mine an ore once it can actually see it, so it won't do or know anything that a normal player couldn't. If you don't want it to look like you're X-Raying, turn this on This will always explore, regardless of exploreForBlocks","descriptionRu":"Включает или отключает функцию: «legit» добычи."},{"name":"legitMineYLevel","type":"Integer","defaultValue":"-59","category":"Добыча и поиск","description":"What Y level to go to for legit strip mining","descriptionRu":"Задаёт числовое ограничение: «legit» добычи «ylevel»."},{"name":"legitMineIncludeDiagonals","type":"Boolean","defaultValue":"false","category":"Добыча и поиск","description":"Magically see ores that are separated diagonally from existing ores. Basically like mining around the ores that it finds in case there's one there touching it diagonally, except it checks it un-legit-ly without having the mine blocks to see it. You can decide whether this looks plausible or not. This is disabled because it results in some weird behavior. For example, it can \"\"\"see\"\"\" the top block of a vein of iron_ore through a lava lake. This isn't an issue normally since it won't consider anything touching lava, so it just ignores it. However, this setting expands that and allows it to see the entire vein so it'll mine under the lava lake to get the iron that it can reach without mining blocks adjacent to lava. This really defeats the purpose of legitMine since a player could never do that lol, so thats one reason why its disabled","descriptionRu":"Включает или отключает функцию: «legit» добычи «include» «diagonals»."},{"name":"forceInternalMining","type":"Boolean","defaultValue":"true","category":"Прочее","description":"When mining block of a certain type, try to mine two at once instead of one. If the block above is also a goal block, set GoalBlock instead of GoalTwoBlocks If the block below is also a goal block, set GoalBlock to the position one down instead of GoalTwoBlocks","descriptionRu":"Включает или отключает функцию: «force» «internal» добычи."},{"name":"internalMiningAirException","type":"Boolean","defaultValue":"true","category":"Прочее","description":"Modification to the previous setting, only has effect if forceInternalMining is true If true, only apply the previous setting if the block adjacent to the goal isn't air.","descriptionRu":"Включает или отключает функцию: «internal» добычи «air» «exception»."},{"name":"followOffsetDistance","type":"Double","defaultValue":"0","category":"Прочее","description":"The actual GoalNear is set this distance away from the entity you're following For example, set followOffsetDistance to 5 and followRadius to 0 to always stay precisely 5 blocks north of your follow target.","descriptionRu":"Задаёт числовое ограничение: следования смещения расстояния."},{"name":"followOffsetDirection","type":"Float","defaultValue":"0","category":"Прочее","description":"The actual GoalNear is set in this direction from the entity you're following. This value is in degrees.","descriptionRu":"Настраивает параметр: следования смещения «direction». Раздел: Прочее."},{"name":"followRadius","type":"Integer","defaultValue":"3","category":"Прочее","description":"The radius (for the GoalNear) of how close to your target position you actually have to be","descriptionRu":"Задаёт числовое ограничение: следования радиуса."},{"name":"followTargetMaxDistance","type":"Integer","defaultValue":"0","category":"Прочее","description":"The maximum distance to the entity you're following","descriptionRu":"Задаёт числовое ограничение: следования «target» максимального расстояния."},{"name":"disableCompletionCheck","type":"Boolean","defaultValue":"false","category":"Прочее","description":"Turn this on if your exploration filter is enormous, you don't want it to check if it's done, and you are just fine with it just hanging on completion","descriptionRu":"Включает или отключает функцию: «disable» «completion» «check»."},{"name":"cachedChunksExpirySeconds","type":"Long","defaultValue":"-1","category":"Поиск пути","description":"Cached chunks (regardless of if they're in RAM or saved to disk) expire and are deleted after this number of seconds -1 to disable I would highly suggest leaving this setting disabled (-1). The only valid reason I can think of enable this setting is if you are extremely low on disk space and you play on multiplayer, and can't take (average) 300kb saved for every 512x512 area. (note that more complicated terrain is less compressible and will take more space) However, simply discarding old chunks because they are old is inadvisable. Baritone is extremely good at correcting itself and its paths as it learns new information, as new chunks load. There is no scenario in which having an incorrect cache can cause Baritone to get stuck, take damage, or perform any action it wouldn't otherwise, everything is rechecked once the real chunk is in range. Having a robust cache greatly improves long distance pathfinding, as it's able to go around large scale obstacles before they're in render distance. In fact, when the chunkCaching setting is disabled and Baritone starts anew every time, or when you enter a completely new and very complicated area, it backtracks far more often because it has to build up that cache from scratch. But after it's gone through an area just once, the next time will have zero backtracking, since the entire area is now known and cached.","descriptionRu":"Настраивает параметр: «cached» «chunks» «expiry» «seconds». Раздел: Поиск пути."},{"name":"verboseCommandExceptions","type":"Boolean","defaultValue":"false","category":"Чат и команды","description":"Print out ALL command exceptions as a stack trace to stdout, even simple syntax errors","descriptionRu":"Включает или отключает функцию: «verbose» «command» «exceptions»."},{"name":"yLevelBoxSize","type":"Double","defaultValue":"15","category":"Прочее","description":"The size of the box that is rendered when the current goal is a GoalYLevel","descriptionRu":"Задаёт числовое ограничение: «y» «level» «box» размера."},{"name":"colorCurrentPath","type":"Color","defaultValue":"red","category":"Отображение","description":"The color of the current path","descriptionRu":"Настраивает параметр: цвета «current» маршрута. Раздел: Отображение."},{"name":"colorNextPath","type":"Color","defaultValue":"magenta","category":"Отображение","description":"The color of the next path","descriptionRu":"Настраивает параметр: цвета «next» маршрута. Раздел: Отображение."},{"name":"colorBlocksToBreak","type":"Color","defaultValue":"red","category":"Отображение","description":"The color of the blocks to break","descriptionRu":"Настраивает параметр: цвета блоков «to» разрушения. Раздел: Отображение."},{"name":"colorBlocksToPlace","type":"Color","defaultValue":"green","category":"Отображение","description":"The color of the blocks to place","descriptionRu":"Настраивает параметр: цвета блоков «to» установки блоков. Раздел: Отображение."},{"name":"colorBlocksToWalkInto","type":"Color","defaultValue":"magenta","category":"Отображение","description":"The color of the blocks to walk into","descriptionRu":"Настраивает параметр: цвета блоков «to» ходьбы «into». Раздел: Отображение."},{"name":"colorBestPathSoFar","type":"Color","defaultValue":"blue","category":"Отображение","description":"The color of the best path so far","descriptionRu":"Настраивает параметр: цвета «best» маршрута «so» «far». Раздел: Отображение."},{"name":"colorMostRecentConsidered","type":"Color","defaultValue":"cyan","category":"Отображение","description":"The color of the path to the most recent considered node","descriptionRu":"Настраивает параметр: цвета «most» «recent» «considered». Раздел: Отображение."},{"name":"colorGoalBox","type":"Color","defaultValue":"green","category":"Отображение","description":"The color of the goal box","descriptionRu":"Настраивает параметр: цвета цели «box». Раздел: Отображение."},{"name":"colorInvertedGoalBox","type":"Color","defaultValue":"red","category":"Отображение","description":"The color of the goal box when it's inverted","descriptionRu":"Настраивает параметр: цвета «inverted» цели «box». Раздел: Отображение."},{"name":"colorSelection","type":"Color","defaultValue":"cyan","category":"Отображение","description":"The color of all selections","descriptionRu":"Настраивает параметр: цвета выделения. Раздел: Отображение."},{"name":"colorSelectionPos1","type":"Color","defaultValue":"black","category":"Отображение","description":"The color of the selection pos 1","descriptionRu":"Настраивает параметр: цвета выделения «pos1». Раздел: Отображение."},{"name":"colorSelectionPos2","type":"Color","defaultValue":"orange","category":"Отображение","description":"The color of the selection pos 2","descriptionRu":"Настраивает параметр: цвета выделения «pos2». Раздел: Отображение."},{"name":"selectionOpacity","type":"Float","defaultValue":"","category":"Отображение","description":"The opacity of the selection. 0 is completely transparent, 1 is completely opaque","descriptionRu":"Настраивает параметр: выделения прозрачности. Раздел: Отображение."},{"name":"selectionLineWidth","type":"Float","defaultValue":"2","category":"Прочее","description":"Line width of the goal when rendered, in pixels","descriptionRu":"Задаёт числовое ограничение: выделения «line» ширины."},{"name":"renderSelection","type":"Boolean","defaultValue":"true","category":"Отображение","description":"Render selections","descriptionRu":"Управляет отображением выделения в игре."},{"name":"renderSelectionIgnoreDepth","type":"Boolean","defaultValue":"true","category":"Отображение","description":"Ignore depth when rendering selections","descriptionRu":"Управляет отображением выделения игнорирования «depth» в игре."},{"name":"renderSelectionCorners","type":"Boolean","defaultValue":"true","category":"Отображение","description":"Render selection corners","descriptionRu":"Управляет отображением выделения «corners» в игре."},{"name":"useSwordToMine","type":"Boolean","defaultValue":"true","category":"Добыча и поиск","description":"Use sword to mine.","descriptionRu":"Включает или отключает функцию: «use» «sword» «to» добычи."},{"name":"desktopNotifications","type":"Boolean","defaultValue":"false","category":"Чат и команды","description":"Desktop notifications","descriptionRu":"Включает или отключает функцию: «desktop» «notifications»."},{"name":"notificationOnPathComplete","type":"Boolean","defaultValue":"true","category":"Чат и команды","description":"Desktop notification on path complete","descriptionRu":"Включает или отключает функцию: уведомлений «on» маршрута «complete»."},{"name":"notificationOnFarmFail","type":"Boolean","defaultValue":"true","category":"Чат и команды","description":"Desktop notification on farm fail","descriptionRu":"Включает или отключает функцию: уведомлений «on» фермы «fail»."},{"name":"notificationOnBuildFinished","type":"Boolean","defaultValue":"true","category":"Чат и команды","description":"Desktop notification on build finished","descriptionRu":"Включает или отключает функцию: уведомлений «on» строительства «finished»."},{"name":"notificationOnExploreFinished","type":"Boolean","defaultValue":"true","category":"Чат и команды","description":"Desktop notification on explore finished","descriptionRu":"Включает или отключает функцию: уведомлений «on» исследования «finished»."},{"name":"notificationOnMineFail","type":"Boolean","defaultValue":"true","category":"Чат и команды","description":"Desktop notification on mine fail","descriptionRu":"Включает или отключает функцию: уведомлений «on» добычи «fail»."},{"name":"elytraSimulationTicks","type":"Integer","defaultValue":"20","category":"Элитры","description":"The number of ticks of elytra movement to simulate while firework boost is not active. Higher values are computationally more expensive.","descriptionRu":"Задаёт временной параметр: элитр «simulation» тиков."},{"name":"elytraPitchRange","type":"Integer","defaultValue":"25","category":"Элитры","description":"The maximum allowed deviation in pitch from a direct line-of-sight to the flight target. Higher values are computationally more expensive.","descriptionRu":"Настраивает параметр: элитр «pitch» «range». Раздел: Элитры."},{"name":"elytraFireworkSpeed","type":"Double","defaultValue":"1.2","category":"Элитры","description":"The minimum speed that the player can drop to (in blocks/tick) before a firework is automatically deployed.","descriptionRu":"Настраивает параметр: элитр фейерверка скорости. Раздел: Элитры."},{"name":"elytraFireworkSetbackUseDelay","type":"Integer","defaultValue":"15","category":"Элитры","description":"The delay after the player's position is set-back by the server that a firework may be automatically deployed. Value is in ticks.","descriptionRu":"Задаёт временной параметр: элитр фейерверка «setback» «use» задержки."},{"name":"elytraMinimumAvoidance","type":"Double","defaultValue":"0.2","category":"Элитры","description":"The minimum padding value that is added to the player's hitbox when considering which point to fly to on the path. High values can result in points not being considered which are otherwise safe to fly to. Low values can result in flight paths which are extremely tight, and there's the possibility of crashing due to getting too low to the ground.","descriptionRu":"Настраивает параметр: элитр «minimum» избегания. Раздел: Элитры."},{"name":"elytraConserveFireworks","type":"Boolean","defaultValue":"false","category":"Элитры","description":"If enabled, avoids using fireworks when descending along the flight path.","descriptionRu":"Включает или отключает функцию: элитр «conserve» «fireworks»."},{"name":"elytraRenderRaytraces","type":"Boolean","defaultValue":"false","category":"Элитры","description":"Renders the raytraces that are performed by the elytra fly calculation.","descriptionRu":"Включает или отключает функцию: элитр отображение «raytraces»."},{"name":"elytraRenderHitboxRaytraces","type":"Boolean","defaultValue":"false","category":"Элитры","description":"Renders the raytraces that are used in the hitbox part of the elytra fly calculation. Requires {@link #elytraRenderRaytraces}.","descriptionRu":"Включает или отключает функцию: элитр отображение «hitbox» «raytraces»."},{"name":"elytraRenderSimulation","type":"Boolean","defaultValue":"true","category":"Элитры","description":"Renders the best elytra flight path that was simulated each tick.","descriptionRu":"Включает или отключает функцию: элитр отображение «simulation»."},{"name":"elytraAutoJump","type":"Boolean","defaultValue":"false","category":"Элитры","description":"Automatically path to and jump off of ledges to initiate elytra flight when grounded.","descriptionRu":"Включает или отключает функцию: элитр автоматического режима прыжка."},{"name":"elytraNetherSeed","type":"Long","defaultValue":"146008555100680","category":"Элитры","description":"The seed used to generate chunks for long distance elytra path-finding in the nether. Defaults to 2b2t's nether seed.","descriptionRu":"Настраивает параметр: элитр «nether» «seed». Раздел: Элитры."},{"name":"elytraPredictTerrain","type":"Boolean","defaultValue":"false","category":"Элитры","description":"Whether nether-pathfinder should generate terrain based on {@link #elytraNetherSeed}. If false all chunks that haven't been loaded are assumed to be air.","descriptionRu":"Включает или отключает функцию: элитр «predict» «terrain»."},{"name":"elytraAutoSwap","type":"Boolean","defaultValue":"true","category":"Элитры","description":"Automatically swap the current elytra with a new one when the durability gets too low","descriptionRu":"Включает или отключает функцию: элитр автоматического режима «swap»."},{"name":"elytraMinimumDurability","type":"Integer","defaultValue":"5","category":"Элитры","description":"The minimum durability an elytra can have before being swapped","descriptionRu":"Настраивает параметр: элитр «minimum» «durability». Раздел: Элитры."},{"name":"elytraMinFireworksBeforeLanding","type":"Integer","defaultValue":"5","category":"Элитры","description":"The minimum fireworks before landing early for safety","descriptionRu":"Настраивает параметр: элитр минимального «fireworks» «before» «landing». Раздел: Элитры."},{"name":"elytraAllowEmergencyLand","type":"Boolean","defaultValue":"true","category":"Элитры","description":"Automatically land when elytra is almost out of durability, or almost out of fireworks","descriptionRu":"Включает или отключает функцию: элитр разрешение «emergency» «land»."},{"name":"elytraTimeBetweenCacheCullSecs","type":"Long","defaultValue":"","category":"Элитры","description":"Time between culling far away chunks from the nether pathfinder chunk cache","descriptionRu":"Настраивает параметр: элитр «time» «between» кэша «cull» «secs». Раздел: Элитры."},{"name":"elytraCacheCullDistance","type":"Integer","defaultValue":"5000","category":"Элитры","description":"Maximum distance chunks can be before being culled from the nether pathfinder chunk cache","descriptionRu":"Задаёт числовое ограничение: элитр кэша «cull» расстояния."},{"name":"elytraAllowLandOnNetherFortress","type":"Boolean","defaultValue":"false","category":"Элитры","description":"Should elytra consider nether brick a valid landing block","descriptionRu":"Включает или отключает функцию: элитр разрешение «land» «on» «nether» «fortress»."},{"name":"elytraTermsAccepted","type":"Boolean","defaultValue":"false","category":"Элитры","description":"Has the user read and understood the elytra terms and conditions","descriptionRu":"Включает или отключает функцию: элитр «terms» «accepted»."},{"name":"elytraChatSpam","type":"Boolean","defaultValue":"false","category":"Элитры","description":"Verbose chat logging in elytra mode","descriptionRu":"Включает или отключает функцию: элитр чата «spam»."}];
